package org.sleepwell.app;
import android.content.Context;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Own-file cleanup journal. It never names or removes original audio files. */
final class LibraryAudioImportJournal {
 final Context app;final String owner=UUID.randomUUID().toString();final File journal;final List<String> names=new ArrayList<>();
 private static File root(Context app)throws IOException{File base=app.getFilesDir().getCanonicalFile(),root=new File(base,"audio-import-journals").getCanonicalFile();if(!base.equals(root.getParentFile())||!root.isDirectory()&&!root.mkdirs())throw new IOException("Import cleanup storage unavailable.");return root;}
 LibraryAudioImportJournal(Context app,int count)throws Exception{this.app=app.getApplicationContext();journal=new File(root(app),owner+".json");for(int n=0;n<count;n++){String name=String.format(Locale.ROOT,"restore-%s-%03d.wav",owner,n+1);if(FileSafety.clip(app,name).exists())throw new IOException("A fresh import destination is unavailable.");names.add(name);}JSONObject data=new JSONObject().put("version",1).put("owner",owner).put("files",new JSONArray(names));AtomicFile atomic=new AtomicFile(journal);FileOutputStream out=null;try{out=atomic.startWrite();out.write(data.toString().getBytes(StandardCharsets.UTF_8));atomic.finishWrite(out);}catch(Exception failed){if(out!=null)atomic.failWrite(out);throw failed;}}
 String name(int index){return names.get(index);}
 void cleanup(Store store)throws Exception{cleanupOne(app,store,journal);}
 static void recover(Context app,Store store)throws Exception{synchronized(SoundClips.LOCK){File[] files=root(app).listFiles();if(files==null||files.length>256)throw new IOException("Import cleanup needs attention.");for(File file:files)if(file.getName().matches("[0-9a-f-]{36}\\.json"))cleanupOne(app,store,file);}}
 private static void cleanupOne(Context app,Store store,File file)throws Exception{synchronized(SoundClips.LOCK){String raw;try(InputStream in=new AtomicFile(file).openRead()){raw=BackupIo.read(in,()->true);}JSONObject data=new JSONObject(raw);String owner=data.getString("owner");if(!BackupRuntime.nonce(owner)||!file.getName().equals(owner+".json")||data.getInt("version")!=1)throw new IOException("Import cleanup needs attention.");JSONArray names=data.getJSONArray("files");if(names.length()>LibraryAudioArchive.MAX_CLIPS)throw new IOException("Import cleanup needs attention.");for(int n=0;n<names.length();n++){String name=names.getString(n);if(!name.matches("restore-"+owner+"-[0-9]{3}\\.wav"))throw new IOException("Invalid import cleanup entry.");if(store.rows("SELECT id FROM clips WHERE path=? LIMIT 1",name).isEmpty()){File audio=FileSafety.clip(app,name);if(audio.exists()&&!audio.delete())throw new IOException("Unused import audio could not be removed.");}}new AtomicFile(file).delete();}}
}
